// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und
// werden in der Data Table pw_config gepflegt (n8n-Oberfläche,
// "Data Tables"). HIER stehen nur die FACHLICHEN Werte dieses Workflows.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};

return [{
  json: {
    // ── aus pw_config ──
    paperless_url: pw('paperless_url'),

    // ── fachlich, hier zu pflegen ──
    // tag_kommando: der Auftrag. Er entsteht auf zwei Wegen: Der
    //   Scanner schreibt nach consume/handschrift-scannen/ (Paperless macht
    //   aus dem Unterordner einen Tag), oder ein Mensch setzt ihn von Hand.
    //   DER NAME IST ZUGLEICH EIN ORDNERNAME auf dem Scanner-Ziel: wer ihn
    //   ändert, muss den Ordner mitbenennen.
    // tag_pending:  global, nicht workflow-spezifisch. Solange er hängt,
    //   ruht JEDE Verarbeitung dieses Dokuments ("ein Dokument, eine
    //   Verarbeitung").
    tag_kommando: 'handschrift-scannen',
    tag_pending: 'wird bearbeitet'
  }
}];

// Dokument-ID aus dem Paperless-Aufruf holen.
//
// WIRFT BEWUSST NICHT, wenn keine dabei ist: Ein Auslöser vom Typ
// "Consumption" ruft ohne doc_url auf, weil das Dokument zu dem
// Zeitpunkt noch gar nicht existiert; Paperless setzt den Platzhalter
// dann auf einen leeren String. Ein Kunde darf so einen Auslöser
// anlegen, ohne dass Fehlermails entstehen. Der Workflow endet dann ohne Meldung.
const body = $('Webhook').first().json.body ?? {};
let id = body.doc_id ?? body.id;
if (!id && body.doc_url) {
  id = String(body.doc_url).match(/\/documents\/(\d+)/)?.[1];
}

return [{
  json: Object.assign({}, $('Konfiguration').first().json, {
    doc_id: id ? Number(id) : null,
    grund: id ? null : 'Aufruf ohne Dokument-ID, vermutlich ein Auslöser, der schon beim Einzug feuert. Nichts zu tun.'
  })
}];

// Wächter 2: Ist dieser Workflow für den Aufruf überhaupt zuständig?
//
// Beide Prüfungen schauen auf den ECHTEN Dokumentzustand, nicht auf
// eine Absprache mit Paperless. Damit kann eine geänderte
// Auslöser-Konfiguration nichts kaputtmachen; sie erzeugt höchstens
// Leerläufe.
const cfg = $('Konfiguration').first().json;
const doc_id = $('Auftrag lesen').first().json.doc_id;
const alleTags = $('Tags laden').first().json.results || [];
const doc = $input.first().json;

const finde = (name) => alleTags.find(t => String(t.name).toLowerCase() === String(name).toLowerCase());
const kommando = finde(cfg.tag_kommando);
const pending = finde(cfg.tag_pending);

// Fehlende Tags sind ein echter Einrichtungsfehler und keine
// Zuständigkeitsfrage; hier wird geworfen.
if (!kommando) throw new Error('Tag "' + cfg.tag_kommando + '" existiert nicht in Paperless; bitte anlegen.');
if (!pending) throw new Error('Tag "' + cfg.tag_pending + '" existiert nicht in Paperless; bitte anlegen (das globale "wird bearbeitet").');

const hat = (t) => (doc.tags || []).includes(t.id);

let grund = null;
if (!hat(kommando)) {
  grund = 'Dokument trägt "' + cfg.tag_kommando + '" nicht; der Aufruf kam von einem anderen Auslöser. Nichts zu tun.';
} else if (hat(pending)) {
  grund = 'Dokument ist als "' + cfg.tag_pending + '" markiert; es läuft bereits eine Verarbeitung. Nichts zu tun.';
}

return [{
  json: Object.assign({}, cfg, {
    doc_id,
    tag_kommando_id: kommando.id,
    tag_pending_id: pending.id,
    zustaendig: grund === null,
    grund
  })
}];

// Kommando- und pending-Tag sind in EINEM Aufruf weggeräumt. Der
// Zustand danach trägt keinen der beiden; der Paperless-Auslöser
// greift also nicht erneut, und der Lauf ist zu Ende.
return [{ json: {
  status: 'erledigt',
  doc_id: $('Zuständigkeit prüfen').first().json.doc_id
} }];

// Ende ohne Meldung: kein Fehler, keine Mail. Der Aufruf war schlicht
// nicht für uns. Er taucht in der n8n-Liste als erfolgreicher Lauf auf,
// und der Grund steht im Ergebnis; damit ist nachvollziehbar, WARUM
// nichts passiert ist, ohne dass jemand aufgeschreckt wird.
return [{ json: {
  status: 'übersprungen',
  grund: $json.grund ?? 'unbekannt',
  doc_id: $json.doc_id ?? null
} }];
